# form 0 wins: kappa(z_a,z_a,z_b,z_b) is NOT suppressed by rho^2 -- it is comparable to the marginal
# fourth cumulant, which is what you expect when the non-Gaussianity is generated by a shared source.
# The correction is then  (g4/4) (sigma phi)_a (sigma phi)_b : a rank-one POSITIVE semidefinite
# addition to the covariance, n^2 flops.  The fitted constant 0.002 sits inside the range the shipped
# g4 schedule predicts (g4/4 = 0.0018 to 0.0147).  Refine, and check it holds out.
import numpy as np
import cov4 as CV, ablate as AB
G_S=AB.G_S
FIT=[0,2,4,6]; FIT8=list(range(8)); HOLD=list(range(8,16))
def sc(nets,**kw): return float(np.mean([CV.predict(k,**kw) for k in nets]))
b=sc(FIT); print(f"deployed fit {b:.4e}\n")
print(f"{'spec':34s} {'fit':>11} {'ratio':>8}")
best=(b,None,"deployed")
for A4 in (0.0008,0.0012,0.0016,0.002,0.0025,0.003,0.004):
    f=sc(FIT,A4=A4,form=0)
    if f<best[0]: best=(f,dict(A4=A4,form=0),f"constant A4={A4}")
    print(f"{'constant A4=%.4f'%A4:34s} {f:11.4e} {f/b:8.4f}", flush=True)
